<?php
declare(strict_types=1);namespace App\Booking\Public\Intent;
use App\Booking\Public\PublicTimezone;
final class IntentInput{public static function parse(array $data):array{$allowed=['service_id','method_id','unit_id','staff_id','quantity','date_time','duration_minutes','timezone'];foreach($data as $k=>$v){if(!in_array($k,$allowed,true))throw new \InvalidArgumentException('Unexpected booking intent field');}$d=[];foreach(['service_id','method_id','unit_id','staff_id'] as $f)$d[$f]=IntentField::id($data[$f]??null);$qty=$data['quantity']??null;if(!is_int($qty)||$qty<1||$qty>1000)throw new \InvalidArgumentException('Invalid quantity');$d['quantity']=$qty;$dur=$data['duration_minutes']??null;if(!is_int($dur)||$dur<15||$dur>1440||$dur%15!==0)throw new \InvalidArgumentException('Invalid duration');$d['duration_minutes']=$dur;$d['timezone']=PublicTimezone::parse($data['timezone']??'Australia/Melbourne');$d['date_time']=IntentSchedule::parse((string)($data['date_time']??''),$d['timezone']);return $d;}}
